using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
using System.Text.Json;
namespace Society.Api;
public static class CommunicationAutomationRunner {
 sealed class WorkerAccessor:IHttpContextAccessor{public HttpContext? HttpContext{get;set;}}
 public static async Task Run(AppDb db,CancellationToken ct,IConfiguration config){var now=DateTimeOffset.UtcNow;await using var tx=await db.Database.BeginTransactionAsync(ct);var rules=await db.Set<CommunicationAutomation>().FromSqlInterpolated($"SELECT * FROM \"CommunicationAutomation\" WHERE \"Enabled\"=true AND (\"LastRun\" IS NULL OR \"LastRun\"<{now.AddSeconds(-30)}) ORDER BY \"LastRun\" NULLS FIRST LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var rule=rules.FirstOrDefault();if(rule==null){await tx.CommitAsync(ct);return;}rule.LastRun=now;if(!await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"communications.automations")||!await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"communications.send")){await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return;}
 var sources=new List<(string key,Guid? eventId,Guid? memberId)>();var mapping=new Dictionary<string,string>{{"MemberApplicationReceived","membership.application.created"},{"MemberApproved","membership.created"},{"MemberActivated","membership.updated"},{"EventPublished","event.review.Approve"},{"EventInvitationIssued","event.invitations.created"},{"RegistrationConfirmed","event.registration.created"},{"EventCancelled","event.cancelled"},{"OfficerAppointmentApproved","officer.appointment.decided"},{"AnnouncementPublished","communication.announcement.published"}};
 if(mapping.TryGetValue(rule.Trigger,out var action)){var audits=await db.Audits.AsNoTracking().Where(a=>a.TenantId==rule.TenantId&&a.Action==action&&a.At>=rule.CreatedAt&&a.At.AddMinutes(rule.OffsetMinutes)<=now).OrderByDescending(a=>a.At).Take(100).ToListAsync(ct);foreach(var audit in audits){if(rule.Trigger=="OfficerAppointmentApproved"&&!await db.OfficerAppointments.AnyAsync(ap=>ap.Id==audit.ResourceId&&ap.TenantId==rule.TenantId&&ap.Status=="Approved",ct))continue;if(rule.Trigger is "MemberApproved" or "MemberActivated"&&!await db.Memberships.AnyAsync(m=>m.Id==audit.ResourceId&&m.TenantId==rule.TenantId&&m.Status=="Active",ct))continue;Guid? e=rule.Trigger.StartsWith("Event")?audit.ResourceId:null;Guid? m=rule.Trigger.StartsWith("Member")&&rule.Trigger!="MemberApplicationReceived"?audit.ResourceId:null;if(rule.Trigger=="OfficerAppointmentApproved")m=await db.OfficerAppointments.Where(ap=>ap.Id==audit.ResourceId&&ap.TenantId==rule.TenantId).Select(ap=>(Guid?)ap.MembershipId).SingleAsync(ct);if(rule.Trigger=="RegistrationConfirmed"){var reg=await db.Set<EventRegistration>().AsNoTracking().SingleOrDefaultAsync(r=>r.Id==audit.ResourceId&&r.TenantId==rule.TenantId&&r.Status=="Confirmed",ct);if(reg==null)continue;e=reg.EventId;m=reg.MembershipId;}sources.Add((audit.Id.ToString(),e,m));}}
 else if(rule.Trigger is "EventApproaching" or "RsvpPending"){var events=await db.Set<CommunityEvent>().Where(e=>e.TenantId==rule.TenantId&&e.Status=="Published"&&e.StartsAt.AddMinutes(rule.OffsetMinutes)<=now&&e.EndsAt>=now&&e.StartsAt>=rule.CreatedAt).OrderBy(e=>e.StartsAt).Take(100).ToListAsync(ct);sources.AddRange(events.Select(e=>(e.Id.ToString(),(Guid?)e.Id,(Guid?)null)));}
 else if(rule.Trigger is "MemberBirthday" or "WeddingAnniversary" or "MembershipAnniversary"){var occasionDate=TimeZoneInfo.ConvertTimeBySystemTimeZoneId(now,"Asia/Kolkata");var month=occasionDate.Month;var day=occasionDate.Day;var memberships=rule.Trigger=="MembershipAnniversary"?await db.Memberships.Where(m=>m.TenantId==rule.TenantId&&m.Status=="Active"&&m.JoinedAt.Month==month&&m.JoinedAt.Day==day).Select(m=>new{m.Id,m.Profile}).ToListAsync(ct):await db.Memberships.Where(m=>m.TenantId==rule.TenantId&&m.Status=="Active").Select(m=>new{m.Id,m.Profile}).ToListAsync(ct);foreach(var m in memberships){if(rule.Trigger is "MemberBirthday" or "WeddingAnniversary"){var text=MembershipService.Json(m.Profile)[rule.Trigger=="MemberBirthday"?"dateOfBirth":"anniversary"]?.ToString();if(!DateOnly.TryParse(text,out var dob)||dob.Month!=month||dob.Day!=day)continue;}sources.Add((occasionDate.ToString("yyyy-MM-dd")+":"+m.Id,null,m.Id));}}
 else if(rule.Trigger=="OfficerTermExpiring"){var appointments=await db.OfficerAppointments.Where(ap=>ap.TenantId==rule.TenantId&&ap.Status=="Approved"&&ap.EndsAt.AddMinutes(rule.OffsetMinutes)<=now&&ap.EndsAt>=now).Select(ap=>new{ap.Id,ap.MembershipId}).Take(100).ToListAsync(ct);sources.AddRange(appointments.Select(ap=>(ap.Id.ToString(),(Guid?)null,(Guid?)ap.MembershipId)));}
 else if(rule.Trigger=="Recurring"){var bucket=now.ToUnixTimeSeconds()/(Math.Max(60,rule.RepeatMinutes)*60);sources.Add((bucket.ToString(),null,null));}
 var accessor=new WorkerAccessor{HttpContext=new DefaultHttpContext{User=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.NameIdentifier,rule.AuthorId.ToString())],"Automation"))}};var access=new Access(db,accessor);var members=new MembershipService(db,access);var community=new CommunityService(db,access);var service=new CommunicationService(db,access,members,community,config);
 var processed=0;foreach(var source in sources){if(await db.Set<AutomationExecution>().AnyAsync(e=>e.RuleId==rule.Id&&e.SourceKey==source.key,ct))continue;if(processed++>=50)break;var execution=new AutomationExecution{TenantId=rule.TenantId,RuleId=rule.Id,SourceKey=source.key};db.Add(execution);try{var template=await db.Set<CommunicationTemplate>().AsNoTracking().SingleAsync(t=>t.TenantId==rule.TenantId&&t.Id==rule.TemplateId&&t.Active,ct);var ruleset=JsonSerializer.Deserialize<AudienceRules>(rule.Audience,CommunicationService.JsonOptions)!;var query=await service.Audience(rule.TenantId,rule.UnitId,ruleset);if(source.memberId!=null)query=query.Where(m=>m.Id==source.memberId);if(source.eventId!=null){var e=await db.Set<CommunityEvent>().AsNoTracking().SingleOrDefaultAsync(e=>e.Id==source.eventId&&e.TenantId==rule.TenantId,ct);if(e==null)throw new DomainException("Source event unavailable");var eligible=community.Eligible(e).Select(m=>m.Id);query=query.Where(m=>eligible.Contains(m.Id));if(rule.Trigger=="RsvpPending")query=query.Where(m=>db.Persons.Any(p=>p.Id==m.PersonId&&!db.Set<EventRsvp>().Any(r=>r.TenantId==rule.TenantId&&r.EventId==e.Id&&r.UserId==p.UserId&&r.Response!="No Response")));}var recipients=await service.Resolve(rule.TenantId,query,rule.Channel,source.eventId);execution.Note=recipients.Count(r=>r.Reason=="Eligible")+" eligible recipients";if(rule.TestMode){execution.Status="Tested";continue;}var policy=await service.Policy(rule.TenantId);if(recipients.Count(r=>r.Reason=="Eligible")>policy.HighVolumeThreshold&&!await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"communications.highvolume"))throw new AccessDeniedException();var greetingApproved=rule.Channel=="InApp"&&(rule.Trigger is "MemberBirthday" or "WeddingAnniversary")&&await MailWorker.Authority(db,rule.TenantId,rule.AuthorId,rule.UnitId,"communications.approve");var stages=greetingApproved?"[]":policy.ApprovalStages;var campaign=new CommunicationCampaign{TenantId=rule.TenantId,AuthorId=rule.AuthorId,UnitId=rule.UnitId,AccountId=rule.AccountId,TemplateId=rule.TemplateId,EventId=source.eventId,Name=rule.Name,Channel=rule.Channel,Body=template.Body,Subject=template.Subject,Audience=rule.Audience,Stages=stages,Status=CommunityService.Stages(stages).Length==0?"Scheduled":"Pending Approval"};db.Add(campaign);execution.CampaignId=campaign.Id;execution.Status=campaign.Status;foreach(var r in recipients.Where(r=>r.Reason=="Eligible"))db.Add(new CampaignRecipient{TenantId=rule.TenantId,CampaignId=campaign.Id,MembershipId=r.MembershipId,PersonId=r.PersonId,UserId=r.UserId,Destination=r.Destination,Variables=JsonSerializer.Serialize(r.Variables)});campaign.SnapshotCount=recipients.Count(r=>r.Reason=="Eligible");campaign.SnapshotAt=now;}
 catch(Exception e)when(e is DomainException or AccessDeniedException){execution.Status="Failed";execution.Note=e is DomainException d?d.Message:"Current authority is insufficient";}}
 await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
 }
}
